 * Licensed under commercial license. See LICENSE.md in the package root for more information
 *-------------------------------------------------------------------------------------------
 */
"use client";
import * as e from "react";
const u = (s, c, a) => {
  const [o, t] = e.useState(s), r = e.useCallback(
    (n, l) => {
      t(n);
    },
    [a, t]
  );
  return [o, r];
};
export {
  u as useControlledState
};
